import type {
  PackageType as ApiPackageType,
  Role as ApiRole,
  ShipmentStatus as ApiShipmentStatus,
} from "./generated/graphql";

/**
 * The enums below come from the API's schema (generated by `npm run codegen`).
 * The lists next to them exist because the app needs the values at runtime, and
 * the assertions at the bottom make the compiler fail if a list ever drifts
 * from the API: add a status in the API, run codegen, and this file stops
 * compiling until the app handles it.
 */
/** The main path a shipment travels. */
export const REGULAR_STATUSES = [
  "CREATED",
  "PICKED_UP",
  "IN_TRANSIT",
  "OUT_FOR_DELIVERY",
  "DELIVERED",
] as const;

/** Things that can go wrong along the way. RETURNED and CANCELLED are final. */
export const EXCEPTION_STATUSES = [
  "DELAYED",
  "ON_HOLD",
  "DELIVERY_ATTEMPT_FAILED",
  "RETURNED",
  "CANCELLED",
] as const;

export const SHIPMENT_STATUSES = [...REGULAR_STATUSES, ...EXCEPTION_STATUSES] as const;

export function isExceptionStatus(status: ShipmentStatus): boolean {
  return (EXCEPTION_STATUSES as readonly string[]).includes(status);
}

export type ShipmentStatus = ApiShipmentStatus;

export const PACKAGE_TYPES = ["DOCUMENT", "PARCEL", "FRAGILE", "ELECTRONICS", "OTHER"] as const;
export type PackageType = ApiPackageType;

export const ROLES = ["ADMIN", "DRIVER"] as const;
export type Role = ApiRole;

export type ShipmentEdit = {
  at: string;
  by?: string | null;
  changes: { field: string; from?: string | null; to?: string | null }[];
};

export type StatusEvent = {
  __typename?: "StatusEvent";
  status: ShipmentStatus;
  location: string;
  note?: string | null;
  timestamp: string;
  /** Who made the change. Staff only. */
  updatedBy?: string | null;
};

export type Shipment = {
  __typename?: "Shipment";
  id: string;
  trackingId: string;
  origin: string;
  destination: string;
  receiverName: string;
  senderName?: string | null;
  /** Masked (last 4 digits) unless the viewer is a logged-in admin. */
  receiverPhone?: string | null;
  packageType?: PackageType | null;
  weightKg?: number | null;
  description?: string | null;
  /** ISO date-time, or null when no estimate was given. */
  estimatedDelivery?: string | null;
  currentStatus: ShipmentStatus;
  /** Computed by the API: the statuses this shipment may move to next. */
  allowedNextStatuses?: ShipmentStatus[];
  /** Who received the parcel (set when delivered). */
  deliveredTo?: string | null;
  /** The receiver's 4-digit delivery code. ADMIN accounts only; null otherwise. */
  deliveryOtp?: string | null;
  createdBy?: string | null;
  /** Edit log. Empty unless the viewer is logged-in staff. */
  edits?: ShipmentEdit[];
  history: StatusEvent[];
};

// Compile-time only: each line fails to type-check if the app's list and the API's enum differ.
type SameSet<A, B> = [A] extends [B] ? ([B] extends [A] ? true : false) : false;
type MustBeTrue<T extends true> = T;
export type _EnumsMatchTheApi = [
  MustBeTrue<SameSet<(typeof SHIPMENT_STATUSES)[number], ApiShipmentStatus>>,
  MustBeTrue<SameSet<(typeof PACKAGE_TYPES)[number], ApiPackageType>>,
  MustBeTrue<SameSet<(typeof ROLES)[number], ApiRole>>,
];
